rule_yaml:
rules:
  - id: dubbo-npe-c1-r3
    languages:
      - java
    severity: ERROR
    message: >-
      A possibly-null value is dereferenced or passed on without a null
      guard: the URL component field 'urlAddress' (left null by the no-arg
      constructor chain URL() / ServiceConfigURL() / URLBuilder()), the
      result of a nullable service-info lookup (getServiceInfo() /
      getValidServiceInfo(), which return null when no matching ServiceInfo
      exists), or a URL credential local (username / password) that is
      assigned only inside a conditional parse branch and therefore stays
      null when the inline user:password@ segment is missing (for example the
      URL body was truncated at '#'). The unguarded use throws a
      NullPointerException. Guard the value before using it, e.g. if (x ==
      null) return ...; / if (x != null) { ... } / x == null ? ... :
      x.method() / default it from a fallback source.
    paths:
      exclude:
        - "**/src/test/**"
        - "**/test/**"
    patterns:
      - pattern-either:
          - patterns:
              - pattern: $LOOKUP(...).$M(...)
              - metavariable-regex:
                  metavariable: $LOOKUP
                  regex: (getServiceInfo|getValidServiceInfo)
          - patterns:
              - pattern-inside: |
                  $TYPE $SI = $LOOKUP(...);
                  ...
              - metavariable-regex:
                  metavariable: $LOOKUP
                  regex: (getServiceInfo|getValidServiceInfo)
              - pattern: $SI.$M(...)
              - pattern-not-inside: |
                  if (<... null == $SI ...>) {
                    ...
                  }
              - pattern-not-inside: |
                  if (<... $SI == null ...>) {
                    ...
                  }
              - pattern-not-inside: |
                  if (<... null != $SI ...>) {
                    ...
                  }
              - pattern-not-inside: |
                  if (<... $SI != null ...>) {
                    ...
                  }
              - pattern-not-inside: |
                  null == $SI ? $A : $SI.$M(...)
              - pattern-not-inside: |
                  $SI == null ? $A : $SI.$M(...)
              - pattern-not-inside: |
                  null != $SI ? $SI.$M(...) : $A
              - pattern-not-inside: |
                  $SI != null ? $SI.$M(...) : $A
          - patterns:
              - pattern-either:
                  - pattern: |
                      $T $V = urlAddress.$M(...);
                      return $R($V);
                  - pattern: |
                      return urlAddress.$M(...);
              - pattern-not-inside: |
                  if (<... urlAddress == null ...>) {
                    ...
                  }
              - pattern-not-inside: |
                  if (<... urlAddress != null ...>) {
                    ...
                  }
              - pattern-not-inside: |
                  urlAddress == null ? $A : $B
              - pattern-not-inside: |
                  urlAddress != null ? $A : $B
              - pattern-not-inside: |
                  if (...) {
                    ...
                  }
          - patterns:
              - pattern-inside: |
                  URL $M(...) {
                    ...
                  }
              - pattern-either:
                  - pattern: |
                      $TYPE $V = null;
                      ...
                      new $CTOR(..., $V, ...);
                  - pattern: |
                      $TYPE $V = null;
                      ...
                      $F(..., $V, ...);
              - metavariable-regex:
                  metavariable: $V
                  regex: ^(username|password)$
              - pattern-not: |
                  $TYPE $V = null;
                  ...
                  if (<... $V == null ...>) {
                    ...
                  }
                  ...
                  new $CTOR(..., $V, ...);
              - pattern-not: |
                  $TYPE $V = null;
                  ...
                  if (<... $V == null ...>) {
                    ...
                  }
                  ...
                  $F(..., $V, ...);
              - pattern-not-inside: |
                  $TYPE $V = null;
                  ...
                  if (<... $V == null ...>) {
                    ...
                  }
                  ...
                  new $CTOR(..., $V, ...);
              - pattern-not-inside: |
                  $TYPE $V = null;
                  ...
                  if (<... $V == null ...>) {
                    ...
                  }
                  ...
                  $F(..., $V, ...);
